function updateVisuals(){const building=state.phase==='assembly',myNext=state.parts.find(q=>q.owner===state.selected&&(q.stage==='carried'||q.stage==='shelf'));ship.children.forEach(o=>{const id=o.userData.partId;if(!id)return;const p=state.parts.find(q=>q.id===id);o.visible=!building||p?.stage==='positioned'||p?.stage==='secured';});partVisuals.forEach(v=>{const p=v.part;v.shelf.visible=state.phase==='assembly'&&p.stage==='shelf';v.install.visible=!!state.cutaway&&(p.stage==='positioned'||p.stage==='secured');v.ghost.visible=state.phase==='assembly'&&(p.stage==='carried'||p===myNext);v.bolts.forEach((b,i)=>{b.visible=state.phase==='assembly'&&p.stage==='positioned';b.material=material(p.bolts[i]>=1?'#d5f591':colFor(p),.1,.3,true);b.scale.setScalar(p.bolts[i]>=1?.65:1);});v.carry.visible=p.stage==='carried';if(v.carry.visible){const actor=actors[p.owner].group,forward=new THREE.Vector3(0,0,1).applyAxisAngle(new THREE.Vector3(0,1,0),actor.rotation.y);v.carry.position.copy(actor.position).addScaledVector(forward,.8);v.carry.position.y+=1.1;v.carry.rotation.y=actor.rotation.y+state.rotation[p.owner]*Math.PI/2;}});cargoVisuals.forEach(v=>{const carrier=state.carry.indexOf('cargo:'+v.cargo.id);v.group.visible=!v.cargo.stowed;if(carrier>=0){const a=actors[carrier].group;v.group.position.copy(a.position).add(new THREE.Vector3(Math.sin(a.rotation.y)*.75,.7,Math.cos(a.rotation.y)*.75));}else v.group.position.fromArray(v.cargo.position);});placedCargo.children.forEach((g,i)=>g.visible=state.cargo[i].stowed);panels.forEach(v=>{v.group.position.copy(ship.position).add(new THREE.Vector3(...v.panel.offset));v.plate.visible=!v.panel.removed;v.plate.material=material(v.panel.health<60?'#b4566d':'#a0acc1',.4,.6,v.panel.health<60);});}
